import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-111: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short111', durationInSeconds: 29.8, fps: 30, width: 1080, height: 1920 };

const B1 = secToFrame(3.5);
const B2 = secToFrame(10.4);
const B3 = secToFrame(14.2);
const B4 = secToFrame(20.7);
const CTA = secToFrame(27.6);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short111: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-111/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="OPENAI VOICE API" lines={[{ text: 'FULL $32 IN' },{ text: 'MINI $10 IN', accent: true }]} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="Realtime 2.1" tagline="The full voice model." chip="$32 / $64" at={B1 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="audio in /1M" v="$32.00" bad />
            <Line k="audio out /1M" v="$64.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="Realtime 2.1 Mini" tagline="The cheaper twin." chip="$10 / $20" at={B2 - 2}>
          <Panel>
            <Line k="audio in /1M" v="$10.00" good />
            <Line k="audio out /1M" v="$20.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="The gap" tagline="Mini is cheaper." chip="3.2X" at={B3 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="input" v="3.2x cheaper" good />
            <Line k="output" v="3.2x cheaper" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Price only" tagline="Quality not compared." chip="FINE PRINT" at={B4 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Full out" v="$64" bad />
            <Line k="Mini out" v="$20" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-111/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="OPENAI VOICE API" lines={[{ text: 'FULL $32 IN' },{ text: 'MINI $10 IN', accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Ten beats thirty-two.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short111;
